import { MeshBasicNodeMaterial, MeshStandardNodeMaterial } from 'three/webgpu';
import { gsap } from 'gsap';

function roundedShape(THREE, width, height, radius) {
  const shape = new THREE.Shape();
  const x = -width * 0.5;
  const y = -height * 0.5;
  const r = Math.min(radius, width * 0.5, height * 0.5);

  shape.moveTo(x + r, y);
  shape.lineTo(x + width - r, y);
  shape.absarc(x + width - r, y + r, r, -Math.PI * 0.5, 0, false);
  shape.lineTo(x + width, y + height - r);
  shape.absarc(x + width - r, y + height - r, r, 0, Math.PI * 0.5, false);
  shape.lineTo(x + r, y + height);
  shape.absarc(x + r, y + height - r, r, Math.PI * 0.5, Math.PI, false);
  shape.lineTo(x, y + r);
  shape.absarc(x + r, y + r, r, Math.PI, Math.PI * 1.5, false);

  return shape;
}

export default function createNode(config, ctx) {
  const THREE = ctx.THREE;
  const root = new THREE.Group();
  const resources = [];
  const animationTimelines = [];
  let disposed = false;

  const width = 1.72;
  const height = 0.46;

  const edgeGeometry = new THREE.ShapeGeometry(
    roundedShape(THREE, width, height, 0.18)
  );

  const edgeMaterial = new MeshBasicNodeMaterial({
    color: '#ff2a38',
    transparent: true,
    opacity: 0.72,
    depthWrite: false
  });

  const edge = new THREE.Mesh(edgeGeometry, edgeMaterial);
  edge.position.z = -0.012;
  root.add(edge);

  const surfaceGeometry = new THREE.ShapeGeometry(
    roundedShape(THREE, width - 0.06, height - 0.06, 0.15)
  );

  const surfaceMaterial = new MeshStandardNodeMaterial({
    color: '#16161d',
    roughness: 0.62,
    metalness: 0.42
  });

  const surface = new THREE.Mesh(surfaceGeometry, surfaceMaterial);
  surface.position.z = 0.012;
  root.add(surface);

  resources.push(edgeGeometry, surfaceGeometry, edgeMaterial, surfaceMaterial);

  const edgeLight = new THREE.PointLight('#ff2a38', 0.3, 1.4, 2);
  edgeLight.position.set(0, 0, 0.22);
  root.add(edgeLight);

  const items = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  for (const item of items) {
    if (!item || typeof item.text !== 'string') continue;

    const label = ctx.fontAtlas.createText(item.text, {
      fontSize: item.typography?.fontSize ?? 0.09,
      color: item.role === 'accent' ? '#ff2a38' : '#e8ecf2',
      align: 'center',
      letterSpacingPx: item.role === 'label' ? 1.2 : 0
    });

    label.position.z = 0.035;
    root.add(label);
  }

  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((texture) => {
      if (disposed) return;

      if ('colorSpace' in texture && THREE.SRGBColorSpace) {
        texture.colorSpace = THREE.SRGBColorSpace;
      }

      texture.wrapS = THREE.ClampToEdgeWrapping;
      texture.wrapT = THREE.ClampToEdgeWrapping;
      surfaceMaterial.map = texture;
      surfaceMaterial.needsUpdate = true;
      resources.push(texture);
    });
  }

  const restY = root.position.y;
  const restScale = root.scale.clone();
  let hoverTimeline = null;
  let pressTimeline = null;

  const animateHover = (active) => {
    if (hoverTimeline) hoverTimeline.kill();

    hoverTimeline = gsap.timeline();
    animationTimelines.push(hoverTimeline);

    hoverTimeline.to(root.position, {
      y: active ? restY + 0.15 : restY,
      duration: 0.5,
      ease: 'power3.out'
    });

    hoverTimeline.to(edgeMaterial, {
      opacity: active ? 1 : 0.72,
      duration: 0.3,
      ease: 'power2.out'
    }, 0);

    hoverTimeline.to(edgeLight, {
      intensity: active ? 0.9 : 0.3,
      duration: 0.3,
      ease: 'power2.out'
    }, 0);
  };

  const press = () => {
    if (pressTimeline) pressTimeline.kill();

    pressTimeline = gsap.timeline();
    animationTimelines.push(pressTimeline);

    pressTimeline
      .to(root.scale, {
        x: restScale.x * 0.97,
        y: restScale.y * 0.97,
        z: restScale.z * 0.97,
        duration: 0.12,
        ease: 'power2.out'
      })
      .to(root.scale, {
        x: restScale.x,
        y: restScale.y,
        z: restScale.z,
        duration: 0.42,
        ease: 'back.out(2.2)'
      });
  };

  root.userData.handlers = {
    hover: (active = true) => animateHover(active),
    pointerenter: () => animateHover(true),
    pointerleave: () => animateHover(false),
    focus: () => {
      edgeMaterial.opacity = 1;
      edgeLight.intensity = 1;
    },
    blur: () => {
      edgeMaterial.opacity = 0.72;
      edgeLight.intensity = 0.3;
    },
    click: () => {
      press();
      ctx.emit('hub-pricing.select', { node: root });
    }
  };

  root.userData.cleanup = () => {
    if (disposed) return;
    disposed = true;

    for (const timeline of animationTimelines) {
      timeline.kill();
    }

    for (const resource of resources) {
      if (resource && typeof resource.dispose === 'function') {
        resource.dispose();
      }
    }

    root.clear();
  };

  return root;
}
